```c
#include <stdio.h>

int main(void) {
    int x[6];
    for (int i = 0; i < 6; i++) {
        if (scanf("%d", &x[i]) != 1) return 0;
    }

    for (int a = 0; a < 6; a++) {
        for (int b = 0; b < 6; b++) {
            if (b == a) continue;
            for (int c = 0; c < 6; c++) {
                if (c == a || c == b) continue;

                int target = x[a];
                if (x[b] + x[c] != target) continue;

                int remaining[3], count = 0;
                for (int i = 0; i < 6; i++) {
                    if (i != a && i != b && i != c) {
                        remaining[count++] = x[i];
                    }
                }

                if (remaining[0] + remaining[1] + remaining[2] == target) {
                    printf("S\n");
                    return 0;
                }
            }
        }
    }

    printf("N\n");
    return 0;
}
```

